-- ISO-46001-01 · attest_iso_46001_01_cr_001 — Nachweis: 4.1
update public.fields set verification_status='verified_against_standard', verification_quote='The organization shall determine external and internal issues that are relevant to its purpose and that affect its ability to achieve the intended outcome(s) of its water efficiency management system. — printed p.8', verification_note='md-verified 2026-09-05 (§4.1, printed p.8) [VA — PDF text layer] — attestation checkbox for gate CR-001 (clause 4.1)', verified_at=now() where id='0c8c63fd-4d1b-46cd-b544-f264c9c97f4f' and verification_status not in ('verified_against_standard','corrected');
