update public.fields set verification_status='verified_against_standard', verification_quote='The organization shall establish water efficiency objectives at relevant functions and levels. The water efficiency objectives shall: a) be consistent with the water efficiency policy; b) be measurable (if practicable); c) take into account applicable requirements; d) be monitored; e) be communicated; f) be updated as appropriate (for example following internal or external benchmarking). The organization shall retain documented information on the water efficiency objectives. — printed p.11', verification_note='md-verified 2026-09-05 (§6.2.1, printed p.11) [VA — PDF text layer]', verified_at=now() where id='28a1ffe1-00db-4b63-bb29-be7b09b7b0e4' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-03 · objective_action_what — Geplante Massnahme (Was)
update public.fields set verification_status='verified_against_standard', verification_quote='When planning how to achieve its water efficiency objectives, the organization shall determine: 1) what will be done; 2) what resources will be required; 3) who will be responsible; 4) when it will be completed; 5) how the results will be evaluated. — printed p.11', verification_note='md-verified 2026-09-05 (§6.2.1 1), printed p.11) [VA — PDF text layer]', verified_at=now() where id='0a477f04-c3c4-4dea-9f25-deefc7da1856' and verification_status not in ('verified_against_standard','corrected');
