update public.fields set verification_status='verified_against_standard', verification_quote='Water input to be included in a water balance chart consists of types and quantities of: a) water supplied by a water utility to the site; b) other water sources (e.g. sea water, demineralised water, ground water, reclaimed water, rain water). | The water balance can be computed using Formula (C.2). Win = Wout WD + R1 + R2 + R3 = O1 + O2 + O3 + O4 — printed p.33-34', verification_note='md-verified 2026-09-05 (Annex C; Formula (C.2), printed p.33-34) [VA — PDF text layer] — CAVEAT (informative annex): the symbol WD is printed only inside Formulae (C.2)/(C.3); the running text never spells out what WD stands for. Its reading as "water supplied by a water utility to the site" is taken from water-input item a) and from Figure C.1, which is a GRAPHIC whose labels are not in the PDF text layer — that mapping is NOT text-attested', verified_at=now() where id='56ca799d-bba0-4ad8-881d-922037439d15' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-08 · R1 — Andere Wasserquelle 1
update public.fields set verification_status='verified_against_standard', verification_quote='Water input to be included in a water balance chart consists of types and quantities of: a) water supplied by a water utility to the site; b) other water sources (e.g. sea water, demineralised water, ground water, reclaimed water, rain water). | The water balance can be computed using Formula (C.2). Win = Wout WD + R1 + R2 + R3 = O1 + O2 + O3 + O4 — printed p.33-34', verification_note='md-verified 2026-09-05 (Annex C; Formula (C.2), printed p.33-34) [VA — PDF text layer] — CAVEAT: R1 is printed only as a term of Formula (C.2). "Other water source stream 1" is inferred from water-input item b) and from Figure C.1 (a graphic, not in the text layer)', verified_at=now() where id='13cc22c0-9d73-41b4-9c22-813624e4ec41' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-08 · R2 — Andere Wasserquelle 2
