-- ISO-46001-08 · Rpp — Prozesswasser zurück in den Prozess
update public.fields set verification_status='verified_against_standard', verification_quote='The process recycling rate (%) shown in Formula (C.5) only looks at reused/reclaimed streams within the process. Rp ×100 % (C.5) Wp + Rpp where Rp is total reused/recycled water from the process; Wp is incoming water to process; Rpp is reused/ recycled water from process back to process. — printed p.35', verification_note='md-verified 2026-09-05 (Annex C; Formula (C.5), printed p.35) [VA — PDF text layer]', verified_at=now() where id='23726150-faea-43b1-b195-e24d011e9dd1' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-08 · plant_recycling_rate — Anlagen-/Standort-Recyclingrate
update public.fields set verification_status='verified_against_standard', verification_quote='The plant/premises recycling rate (%) calculated by Formula (C.3) looks at all reused/reclaimed streams within the premises. Rp + Rnp ×100 % (C.3) Rp + Rnp +WD where Rp is total reused/recycled water from the process; Rnp is total reused/recycled water not from the process; — printed p.35', verification_note='md-verified 2026-09-05 (Annex C; Formula (C.3), printed p.35) [VA — PDF text layer] — the quote reproduces the stacked 2-D fraction exactly as the text layer flattens it (numerator line "Rp + Rnp x100 %", denominator line "Rp + Rnp +WD"); the encoded (Rp + Rnp) / (Rp + Rnp + WD) * 100 is the faithful linearisation. Dimensionally sound: m3/m3 x 100 = %', verified_at=now() where id='84fc8997-813c-46f3-8ef5-67248ad5253f' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-08 · process_recycling_rate — Prozess-Recyclingrate
update public.fields set verification_status='verified_against_standard', verification_quote='The process recycling rate (%) shown in Formula (C.5) only looks at reused/reclaimed streams within the process. Rp ×100 % (C.5) Wp + Rpp where Rp is total reused/recycled water from the process; Wp is incoming water to process; Rpp is reused/ recycled water from process back to process. — printed p.35', verification_note='md-verified 2026-09-05 (Annex C; Formula (C.5), printed p.35) [VA — PDF text layer] — the quote reproduces the stacked 2-D fraction as flattened by the text layer (numerator "Rp x100 %", denominator "Wp + Rpp"); the encoded Rp / (Wp + Rpp) * 100 is the faithful linearisation. Dimensionally sound: m3/m3 x 100 = %', verified_at=now() where id='6f42e2a6-c624-4fdb-a4f3-6c166bcbddc9' and verification_status not in ('verified_against_standard','corrected');

-- ---------------- ISO-46001-09 — Leistungsbewertung: Monitoring, Audit, Managementbewertung ----------------
-- ISO-46001-09 · attest_iso_46001_09_cr_030 — Nachweis: 9.1
update public.fields set verification_status='verified_against_standard', verification_quote='As a minimum, the water use shall be metered. | In addition, the following shall be undertaken: 1) monitor and measure as a minimum: — the breakdown of types of water supplied or used in the facility, including by source; — the breakdown of significant water use and other outputs of the water use review; | — the relevant variables related to significant water use; — the business activity indicators; — the water efficiency indicators; — the effectiveness of the action plans in achieving objectives and targets; — evaluations of actual versus expected water use. — printed p.17-18', verification_note='md-verified 2026-09-05 (§9.1, printed p.17-18) [VA — PDF text layer] — attestation checkbox for gate CR-030 (clause 9.1)', verified_at=now() where id='66407b86-70b5-4d92-a705-3b9dc44a0bad' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-09 · attest_iso_46001_09_cr_032 — Nachweis: 9.2
update public.fields set verification_status='verified_against_standard', verification_quote='The organization shall conduct internal audits at planned intervals to provide information on whether the water efficiency management system: a) conforms to: — the organization’s own requirements for its water efficiency management system; — the requirements of this document; b) is effectively implemented and maintained. | The organization shall: a) plan, establish, implement and maintain an audit programme(s), including the frequency, methods, responsibilities, planning requirements and reporting, which shall take into consideration the importance of the processes concerned and the results of previous audits; b) define the audit criteria and scope for each audit; c) select auditors and conduct audits to ensure objectivity and impartiality of the audit process; d) ensure that the results of the audits are reported to relevant management; e) retain documented information as evidence of the implementation of the audit programme and the audit results. — printed p.18', verification_note='md-verified 2026-09-05 (§9.2, printed p.18) [VA — PDF text layer] — attestation checkbox for gate CR-032 (clause 9.2)', verified_at=now() where id='4a2b9320-d62c-480d-8be6-48c22388b3c4' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-09 · monitoring_plan — Monitoring- und Messplan
update public.fields set verification_status='verified_against_standard', verification_quote='The organization shall determine: a) what needs to be monitored and measured; b) the methods for monitoring, measurement, analysis and evaluation, as applicable to ensure valid results; c) when the monitoring and measuring shall be performed; d) when the results of the monitoring and measurement shall be analysed and evaluated; — printed p.17', verification_note='md-verified 2026-09-05 (§9.1 a)-d), printed p.17) [VA — PDF text layer]', verified_at=now() where id='99f343f9-8171-4663-850d-d64bcad57404' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-09 · water_use_metered — Wassernutzung erfasst (Zaehler)
update public.fields set verification_status='verified_against_standard', verification_quote='As a minimum, the water use shall be metered. | 3.38 water meter instrument intended to measure continuously, store, and display the volume of water passing through the measurement transducer at metering conditions — printed p.17, 8', verification_note='md-verified 2026-09-05 (§9.1; 3.38, printed p.17, 8) [VA — PDF text layer]', verified_at=now() where id='3a56d77e-8706-45f2-94cf-a2aee2023ee8' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-09 · monitoring_breakdown — Monitoring-Aufschlüsselung
update public.fields set verification_status='verified_against_standard', verification_quote='In addition, the following shall be undertaken: 1) monitor and measure as a minimum: — the breakdown of types of water supplied or used in the facility, including by source; — the breakdown of significant water use and other outputs of the water use review; | — the relevant variables related to significant water use; — the business activity indicators; — the water efficiency indicators; — the effectiveness of the action plans in achieving objectives and targets; — evaluations of actual versus expected water use. — printed p.17-18', verification_note='md-verified 2026-09-05 (§9.1 1), printed p.17-18) [VA — PDF text layer]', verified_at=now() where id='0833897e-49d3-4d30-a65f-b635ec4ad192' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-09 · significant_deviation — Signifikante Abweichung der Wassereffizienz
update public.fields set verification_status='verified_against_standard', verification_quote='3) identify and investigate any significant deviations in water efficiency performance; | The organization shall evaluate the water efficiency performance and the effectiveness of the water efficiency management system. When evaluating its water efficiency performance, the organization shall review its water use and update its action plan in the water efficiency management plan if necessary and possible. — printed p.18', verification_note='md-verified 2026-09-05 (§9.1 3), printed p.18) [VA — PDF text layer] — CAVEAT: §9.1 3) obliges identifying and investigating deviations; recording a deviation VALUE is owed only when one exists, hence correctly is_required=false', verified_at=now() where id='020c2306-181c-4c35-b8cf-e8ff7fa15749' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-09 · compliance_evaluation — Bewertung der Einhaltung von Anforderungen
update public.fields set verification_status='verified_against_standard', verification_quote='4) evaluate compliance with legal requirements or other requirements in regard to water use, water efficiency, wastewater discharge and pollution control. — printed p.18', verification_note='md-verified 2026-09-05 (§9.1 4), printed p.18) [VA — PDF text layer]', verified_at=now() where id='667b88c0-feb4-4b6f-98ea-a6d7191e6ce5' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-09 · internal_audit — Internes Audit
update public.fields set verification_status='verified_against_standard', verification_quote='The organization shall conduct internal audits at planned intervals to provide information on whether the water efficiency management system: a) conforms to: — the organization’s own requirements for its water efficiency management system; — the requirements of this document; b) is effectively implemented and maintained. | 3.1 audit systematic, independent and documented process (3.24) for obtaining audit evidence and evaluating it objectively to determine the extent to which the audit criteria are fulfilled — printed p.18, 2', verification_note='md-verified 2026-09-05 (§9.2.1; 3.1, printed p.18, 2) [VA — PDF text layer]', verified_at=now() where id='3663a7be-defa-4ff3-b672-f9db8d8c11ad' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-09 · audit_programme — Auditprogramm
update public.fields set verification_status='verified_against_standard', verification_quote='The organization shall: a) plan, establish, implement and maintain an audit programme(s), including the frequency, methods, responsibilities, planning requirements and reporting, which shall take into consideration the importance of the processes concerned and the results of previous audits; b) define the audit criteria and scope for each audit; c) select auditors and conduct audits to ensure objectivity and impartiality of the audit process; d) ensure that the results of the audits are reported to relevant management; e) retain documented information as evidence of the implementation of the audit programme and the audit results. — printed p.18', verification_note='md-verified 2026-09-05 (§9.2.2 a)-e), printed p.18) [VA — PDF text layer]', verified_at=now() where id='8f097bf8-804b-41eb-955b-77d3c3b4abea' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-09 · management_review — Managementbewertung
update public.fields set verification_status='verified_against_standard', verification_quote='Top management shall review the organization’s water efficiency management system, at planned intervals, to ensure its continuing suitability, adequacy and effectiveness. The management review shall include consideration of: a) the status of actions from previous management reviews; b) changes in external and internal issues that are relevant to the water efficiency management system; c) information on the water efficiency management system performance, including trends in the: — nonconformities and corrective actions; — monitoring and measurement results; — audit results; d) opportunities for continual improvement. The outputs of the management review shall include decisions related to continual improvement opportunities and any need for changes to the water efficiency management system. Decisions to be made and recorded shall relate to: 1) assessing water efficiency management of the organization; 2) assessing water efficiency policy; 3) the organization’s business activity indicator(s); 4) objectives, targets or other elements of the water efficiency management system, consistent with the organization’s commitment to continual improvement; 5) the allocation of resources. | The organization shall retain documented information as evidence of the results of management reviews. — printed p.19', verification_note='md-verified 2026-09-05 (§9.3, printed p.19) [VA — PDF text layer]', verified_at=now() where id='6518b252-e3fd-4137-b68b-66f7a253f838' and verification_status not in ('verified_against_standard','corrected');

-- ---------------- ISO-46001-10 — Verbesserung: Nichtkonformitaet & kontinuierliche Verbesserung ----------------
-- ISO-46001-10 · attest_iso_46001_10_cr_034 — Nachweis: 10.1
update public.fields set verification_status='verified_against_standard', verification_quote='When a nonconformity occurs, the organization shall: a) react to the nonconformity and, as applicable: — take action to control and correct it; — deal with the consequences; b) evaluate the need for action to eliminate the cause(s) of nonconformities, in order that it does not recur or occur elsewhere, by: — reviewing the nonconformity; — determining the cause of the nonconformity; — determining if similar nonconformities exist, or could potentially occur; | c) implement any action needed; d) review the effectiveness of any corrective action taken; e) make changes to the water efficiency management system, if necessary. Corrective actions shall be appropriate to the effects of the nonconformities encountered. The organization shall retain documented information as evidence of: 1) the nature of the nonconformities and any subsequent actions taken; 2) the results of any corrective action. — printed p.19-20', verification_note='md-verified 2026-09-05 (§10.1, printed p.19-20) [VA — PDF text layer] — attestation checkbox for gate CR-034 (clause 10.1). SCOPE-PREDICATE-FREE: §10.1 triggers only "When a nonconformity occurs" — the gate blocks unconditionally — staged', verified_at=now() where id='77bb1084-aed4-4e5c-bb2f-22d0196f1afb' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-10 · nonconformity — Nichtkonformität
update public.fields set verification_status='verified_against_standard', verification_quote='When a nonconformity occurs, the organization shall: a) react to the nonconformity and, as applicable: — take action to control and correct it; — deal with the consequences; b) evaluate the need for action to eliminate the cause(s) of nonconformities, in order that it does not recur or occur elsewhere, by: — reviewing the nonconformity; — determining the cause of the nonconformity; — determining if similar nonconformities exist, or could potentially occur; | 3.18 nonconformity non-fulfilment of a requirement (3.26) — printed p.19, 4', verification_note='md-verified 2026-09-05 (§10.1; 3.18, printed p.19, 4) [VA — PDF text layer] — CAVEAT: correctly is_required=false — §10.1 obliges action only "When a nonconformity occurs"', verified_at=now() where id='949c9190-fa65-4f52-8869-acee043b8086' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-10 · corrective_action — Korrekturmaßnahme
update public.fields set verification_status='verified_against_standard', verification_quote='c) implement any action needed; d) review the effectiveness of any corrective action taken; e) make changes to the water efficiency management system, if necessary. Corrective actions shall be appropriate to the effects of the nonconformities encountered. The organization shall retain documented information as evidence of: 1) the nature of the nonconformities and any subsequent actions taken; 2) the results of any corrective action. | Corrective actions shall be appropriate to the effects of the nonconformities encountered. | 3.8 corrective action action to eliminate the cause of a nonconformity (3.18) and to prevent recurrence — printed p.20, 3', verification_note='md-verified 2026-09-05 (§10.1 c)-e); 3.8, printed p.20, 3) [VA — PDF text layer] — CAVEAT: correctly is_required=false — owed only once a nonconformity has occurred', verified_at=now() where id='bfc4cfd0-0ca6-459f-b9f6-8dc871433e32' and verification_status not in ('verified_against_standard','corrected');
-- ISO-46001-10 · continual_improvement — Kontinuierliche Verbesserung
update public.fields set verification_status='verified_against_standard', verification_quote='The organization shall continually improve the suitability, adequacy and effectiveness of the water efficiency management system. This will be achieved if the organization takes into account the outputs of the evaluation and the management review to determine the needs or opportunities for improvement. | 3.7 continual improvement recurring activity to enhance performance (3.22) — printed p.20, 3', verification_note='md-verified 2026-09-05 (§10.2; 3.7, printed p.20, 3) [VA — PDF text layer]', verified_at=now() where id='b89461cb-55fe-407b-add9-90e370b983a9' and verification_status not in ('verified_against_standard','corrected');

-- ---------------- equations (4) — worksheet ISO-46001-08, Annex C (INFORMATIVE) ----------------
-- C.1: Win = WD + R1 + R2 + R3
update public.equations set verification_status='verified_against_standard', verification_quote='The water balance equation can be represented by Formula (C.1): Win = Wout (C.1) where Win is total water input; Wout is total water output. | The water balance can be computed using Formula (C.2). Win = Wout WD + R1 + R2 + R3 = O1 + O2 + O3 + O4 — printed p.33-34', verification_note='md-verified 2026-09-05 (Annex C, Formulae (C.1), (C.2), printed p.33-34) [VA — PDF text layer] — the printed identity (C.2) WD + R1 + R2 + R3 = O1 + O2 + O3 + O4 is split by the encoding into its two computed sides; this equation is the inflow side. Faithful. Dimensional check: m3 + m3 + m3 + m3 = m3, consistent with the declared unit of Win. NOTE: Annex C is INFORMATIVE ("(informative)", printed p.33) — no block gate may rest on it', verified_at=now() where id='bf60d386-4a0c-4270-a506-c923cbf074bd' and verification_status <> 'verified_against_standard';
-- C.2b: Wout = O1 + O2 + O3 + O4
update public.equations set verification_status='verified_against_standard', verification_quote='The water balance equation can be represented by Formula (C.1): Win = Wout (C.1) where Win is total water input; Wout is total water output. | The water balance can be computed using Formula (C.2). Win = Wout WD + R1 + R2 + R3 = O1 + O2 + O3 + O4 — printed p.33-34', verification_note='md-verified 2026-09-05 (Annex C, Formulae (C.1), (C.2), printed p.33-34) [VA — PDF text layer] — outflow side of the split printed identity (C.2). Dimensional check: m3 + m3 + m3 + m3 = m3, consistent with Wout. RESIDUE: the printed water-output list on p.33 names FIVE output categories while (C.2) has only FOUR O-terms, which come from the Figure C.1 worked example. Annex C is INFORMATIVE', verified_at=now() where id='0cc90c9a-08fe-4816-9fa9-f2c9f80752f7' and verification_status <> 'verified_against_standard';
-- C.3: plant_recycling_rate = (Rp + Rnp) / (Rp + Rnp + WD) * 100
update public.equations set verification_status='verified_against_standard', verification_quote='The plant/premises recycling rate (%) calculated by Formula (C.3) looks at all reused/reclaimed streams within the premises. Rp + Rnp ×100 % (C.3) Rp + Rnp +WD where Rp is total reused/recycled water from the process; Rnp is total reused/recycled water not from the process; — printed p.35', verification_note='md-verified 2026-09-05 (Annex C, Formula (C.3), printed p.35) [VA — PDF text layer] — the quote is the flattened stacked fraction exactly as printed (numerator "Rp + Rnp x100 %", denominator "Rp + Rnp +WD"); the encoded (Rp + Rnp) / (Rp + Rnp + WD) * 100 is the faithful linearisation and agrees with the printed worked example (C.4), (P1 + P2 + R1 + R2 + R3) / (P1 + P2 + R1 + R2 + R3 + R4 + WD) x 100 %. Dimensional check: m3/m3 x 100 = %, consistent. NOTE: the where-clause defines Rp and Rnp but NOT WD, which appears in the denominator; Annex C is INFORMATIVE', verified_at=now() where id='eeb0aca8-e669-43fc-9c5a-291b54b4eb45' and verification_status <> 'verified_against_standard';
-- C.5: process_recycling_rate = Rp / (Wp + Rpp) * 100
update public.equations set verification_status='verified_against_standard', verification_quote='The process recycling rate (%) shown in Formula (C.5) only looks at reused/reclaimed streams within the process. Rp ×100 % (C.5) Wp + Rpp where Rp is total reused/recycled water from the process; Wp is incoming water to process; Rpp is reused/ recycled water from process back to process. — printed p.35', verification_note='md-verified 2026-09-05 (Annex C, Formula (C.5), printed p.35) [VA — PDF text layer] — flattened stacked fraction as printed (numerator "Rp x100 %", denominator "Wp + Rpp"); the encoded Rp / (Wp + Rpp) * 100 is the faithful linearisation and agrees with the printed worked example (C.6), (P1 + P2) / (B + P1) x 100 %. Dimensional check: m3/m3 x 100 = %, consistent. Annex C is INFORMATIVE', verified_at=now() where id='0b1026ab-9a89-4424-b9de-4ec01e6de1af' and verification_status <> 'verified_against_standard';
